H, W = map(int, input().split())
dp = [[0] * (1 << W) for i in range(W + 1)]
for i in range(H):
    dp[0][int(input(), 2)] += 1
for i in range(W):
    for j in range(i, -1, -1):
        for bit in range(1 << W):
            dp[j + 1][bit ^ (1 << i)] += dp[j][bit]
ans = 1 << 60
for bit in range(1 << W):
    res = 0
    for i in range(W + 1):
        res += min(i, W - i) * dp[i][bit]
    ans = min(ans, res)
print(ans)
